mkdir -p /tmp/closecheck && cat > /tmp/closecheck/vitest.config.ts <<EOF
import { fileURLToPath } from "node:url";
import { defineConfig } from "vitest/config";
export default defineConfig({
  root: "$PWD",
  resolve: { alias: { "@": "$PWD/src" } },
  test: { environment: "node", globals: true, include: ["/tmp/closecheck/*.test.ts"] },
});
EOF
cat > /tmp/closecheck/close.test.ts <<'EOF'
import { useTemporaryDatabase, createTenant } from "$ROOT/tests/server/_support/fixtures";
import * as orgService from "@/server/services/organization-service";
import * as sessionService from "@/server/services/session-service";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { toAppError } from "@/lib/errors";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());

test("close", async () => {
  const t = await createTenant("acme");
  const other = await createTenant("globex");
  await usageRepo.getUsage(t.org.id); await usageRepo.getUsage(other.org.id);
  const owner = t.actors.owner;
  await expect(orgService.deleteOrganization(owner, { orgId: t.org.id, confirmSlug: "nope" })).rejects.toThrow();
  expect((await orgService.listOrganizationsForUser(owner.userId)).length).toBe(1);
  await orgService.deleteOrganization(owner, { orgId: t.org.id, confirmSlug: "acme" });
  expect(await orgService.listOrganizationsForUser(owner.userId)).toEqual([]);
  expect(await orgService.resolveOrgBySlug("acme")).toBeNull();
  const principal = { userId: owner.userId, email: "x", activeOrgId: t.org.id, expiresAt: "2099-01-01T00:00:00.000Z" } as never;
  expect(await sessionService.resolveActorForOrg(principal, "acme")).toBeNull();
  expect((await subscriptionRepo.findSubscription(t.org.id))?.status).toBe("canceled");
  expect(await usageRepo.listOrgIdsForRollup(50)).toEqual([other.org.id]);
  const err = await orgService.deleteOrganization(owner, { orgId: t.org.id, confirmSlug: "acme" }).catch((e) => e);
  expect(toAppError(err).code).toBe("conflict");
  const created = await orgService.createOrganization(owner.userId, { name: "New", slug: "acme", plan: "free" });
  expect(created.slug).not.toBe("acme");
});
EOF
sed -i '' "s#\$ROOT#$PWD#" /tmp/closecheck/close.test.ts
npx vitest run --config /tmp/closecheck/vitest.config.ts 2>&1 | grep -v "npm warn" | tail -30

